CREATE OR REPLACE PACKAGE BODY OPHARAPP.PKG_PNJ_NULL
IS
   FUNCTION get_data_pnj (in_noagenda         IN     VARCHAR2,
                          tiket          IN     OPHARAPP.usman_kct.tiket%TYPE,
                          out_data          OUT SYS_REFCURSOR,
                          out_rowcount      OUT NUMBER,
                          out_message       OUT VARCHAR2)
      RETURN INT
   IS
      CEK_ADA          VARCHAR (100);
      CEK_EMAIL_BARU   VARCHAR (100);
   BEGIN
      OPEN out_data FOR
      SELECT PNJ_PEMOHON,NOAGENDA, NOBANG_PEMOHON
           FROM BILL52.TRANS_101_PEMOHON
          WHERE NOAGENDA = in_noagenda;
      out_rowcount := SQL%ROWCOUNT;

      IF out_rowcount >= 1
      THEN
         out_message := 'Sukses';
         RETURN 1;
      ELSE
         out_message := 'Maaf Data  tidak Ditemukan';
         RETURN 0;
      END IF;
   EXCEPTION
      WHEN OTHERS
      THEN
         out_message := SQLERRM;
         RETURN 0;
   END;


   PROCEDURE save_pnj        (in_plogin     IN     VARCHAR2,
                              in_tiket             IN     VARCHAR2,
                              in_noagenda          IN     VARCHAR2,
                              in_pnj_101           IN     VARCHAR2,
                              in_pnj_pemohon       IN     VARCHAR2,
                              in_pnj_106           IN     VARCHAR2,
                              in_nobang_101        IN     VARCHAR2,
                              in_nobang_pemohon    IN     VARCHAR2,
                              in_nobang_106        IN     VARCHAR2,
                             in_ketnobang_101      IN     VARCHAR2,
                             in_ketnobang_pemohon  IN     VARCHAR2,
                             in_ketnobang_106      IN     VARCHAR2,
                              out_rowcount            OUT NUMBER,
                              msgerror                OUT VARCHAR2)
   IS
      vjml         NUMBER;
      vemail       VARCHAR2 (200);
      vunit        VARCHAR2 (5);
      vuserlevel   VARCHAR2 (5);
      vnama        VARCHAR2 (30);
      vjabatan     VARCHAR2 (100);
      vaktif       INTEGER;
      vgm          INTEGER;
      vcc          VARCHAR2 (1000);
      vnip         VARCHAR2 (100);
   BEGIN
      SELECT COUNT (*)
        INTO vjml
        FROM BILL52.TRANS_101 a
       WHERE a.NOAGENDA = in_noagenda;


      IF vjml = 0
      THEN
         msgerror := 'Data tidak ditemukan!';
      ELSE
         INSERT INTO OPHARAPP.TRANS_101_LOG
           (NOAGENDA, TGLAGENDA, TGLJAWABAN_101, TGLJATUHTEMPO_101, TGLCATAT, PETUGASCATAT, TGLEDIT, PETUGASEDIT, NOKOLEKTIF, PAKET, VIALAYANAN, FILLER_10, FILLER_11, FILLER_12, MK, JENIS_MK, KET_MOHON_A, KET_MOHON_B, KET_MOHON_C, KET_MOHON_D, KET_MOHON_E, NAMA, KDRUBAH_NOURUTPLG, NOURUTPLG, NPWP, TARIF, KDPT, KDPT_2, DAYA, KDAYA, PNJ, NAMAPNJ, NOBANG, KETNOBANG, RT, RW, NODLMRT, KETNODLMRT, LINGKUNGAN, KODEPOS, NOTELP, IDENTITAS, NOIDENTITAS, EMAIL, KEPERLUAN, NODENAH_PLG, FILEBLOB, IDPEL_TETANGGA, UNITUP, IDPEL, TGL_106, NAMA_INSTALATIR, JENIS_TRANSAKSI, KD_PAKET_SAR, NOPEL, DAYAJBST, FAKNPREMIUM, JMLKOLEKTIF, TGLBATAL, BATALBY, ALASANBATAL, FLAG_RPADMIN, NOTELP_HP, BP_HIBAH, RPBPHIBAH, RPBP, KODETDL, UNITMOHON, KELURAHAN, PROSENPPJ, PEMDA, KOORDINAT_X, KOORDINAT_Y, KD_KEPERLUAN, KD_KABKOTA, TGL_SLO, NOREGSLO, PAKETSLO,
           FLAGINSTALASI, TGLINSTALASISIAP, NO_SLO, DAYAMOHON, FLAGREKOMENDASI, NOSURATREKOMENDASI, NO_TIKET, PLOGIN, TGL_LOG)
           SELECT  NOAGENDA, TGLAGENDA, TGLJAWABAN_101, TGLJATUHTEMPO_101, TGLCATAT, PETUGASCATAT, TGLEDIT, PETUGASEDIT, NOKOLEKTIF, PAKET, VIALAYANAN, FILLER_10, FILLER_11, FILLER_12, MK, JENIS_MK, KET_MOHON_A, KET_MOHON_B, KET_MOHON_C, KET_MOHON_D, KET_MOHON_E, NAMA, KDRUBAH_NOURUTPLG, NOURUTPLG, NPWP, TARIF, KDPT, KDPT_2, DAYA, KDAYA, PNJ, NAMAPNJ, NOBANG, KETNOBANG, RT, RW, NODLMRT, KETNODLMRT, LINGKUNGAN, KODEPOS, NOTELP, IDENTITAS, NOIDENTITAS, EMAIL, KEPERLUAN, NODENAH_PLG, FILEBLOB, IDPEL_TETANGGA, UNITUP, IDPEL, TGL_106, NAMA_INSTALATIR, JENIS_TRANSAKSI, KD_PAKET_SAR, NOPEL, DAYAJBST, FAKNPREMIUM, JMLKOLEKTIF, TGLBATAL, BATALBY, ALASANBATAL, FLAG_RPADMIN, NOTELP_HP, BP_HIBAH, RPBPHIBAH, RPBP, KODETDL, UNITMOHON, KELURAHAN, PROSENPPJ, PEMDA, KOORDINAT_X, KOORDINAT_Y, KD_KEPERLUAN, KD_KABKOTA, TGL_SLO, NOREGSLO, PAKETSLO,
           FLAGINSTALASI, TGLINSTALASISIAP, NO_SLO, DAYAMOHON, FLAGREKOMENDASI, NOSURATREKOMENDASI, in_tiket, in_plogin, SYSDATE FROM BILL52.TRANS_101 WHERE NOAGENDA=in_noagenda;
            
         INSERT into opharapp.trans_101_pemohon_log
            Select NOAGENDA, TGLCATAT, PETUGASCATAT, TGLEDIT, PETUGASEDIT, FILLER_02, NAMA_PEMOHON, PNJ_PEMOHON, NAMAPNJ_PEMOHON, 
            NOBANG_PEMOHON, KETNOBANG_PEMOHON, RT_PEMOHON, RW_PEMOHON, NODLMRT_PEMOHON, KETNODLMRT_PEMOHON, LINGKUNGAN_PEMOHON, 
            KOTA_PEMOHON, KODEPOS_PEMOHON, NOTELP_PEMOHON, IDENTITAS_PEMOHON, NOIDENTITAS_PEMOHON, EMAIL_PEMOHON, SYSDATE TGLLOG, 
            in_tiket LOGBY, NOTELP_HP_PEMOHON
            from bill52.trans_101_pemohon WHERE NOAGENDA=in_noagenda;
            
          INSERT into opharapp.trans_106_log
            Select NOAGENDA, NO_KOLEKTIF, UNITUP, IDPEL, TGL_106, BANKID, NAMABANK, REFNO, TGLLUNAS_BANK, RP_106, NO_106, NO_REGISTER,
             TGLCATAT, PETUGASCATAT, TGLEDIT, PETUGASEDIT, NOJAMINANINST, TGLJAMINANINST, INSTALATIR, NOSPJBTL, TGLSPJBTL, NOBP, TGLBP,
              RPBP, NOUJL, TGLUJL, RPUJL, KDUJL, FILLER_10, FILLER_11, FILLER_12, MK, JENIS_MK, KET_MOHON_A, KET_MOHON_B, KET_MOHON_C,
               KET_MOHON_D, KET_MOHON_E, NAMA, KDRUBAH_NOURUTPLG, NOURUTPLG, NPWP, TARIF, KDPT, KDPT_2, DAYA, KDAYA, PNJ, NAMAPNJ, 
               NOBANG, KETNOBANG, RT, RW, NODLMRT, KETNODLMRT, LINGKUNGAN, KODEPOS, NOTELP, IDENTITAS, NOIDENTITAS, KEPERLUAN, 
               NODENAH_PLG, FILEBLOB, IDPEL_TETANGGA, TGLPDL, SYSDATE TGLLOG, in_tiket LOGBY, NOPEL
            from bill52.trans_106 WHERE NOAGENDA=in_noagenda;
            
--          insert INTO BILL52.TRANS_PDL_LOG
--            select  NOMORPDL, KDPEMBMETER, DAYA, KDAYA, FRT, NAMAPNJ, KOGOL, KDJENIS_SL, PEMDA, KDINKASO, LETAKDESA, MEREK_PEMBATAS, KODEDESA, TEGANGAN_SL, TYPE_PEMBATAS, KDBPT, MK, KDRUBAH_NOURUTPLG, KDAM, MEREK_SAKLARWAKTU, KDPT, KTEGANGAN_SL, KDPT_2, LETAKAPP, KDPENGGERAK, KDREKG, KDPENGUKURAN, KELASDESA, TARIF, TYPE_SAKLARWAKTU, PNJ, KDPSL, FJN, REF_KDPPJ, KDIND, KDKLP, KDUJL, LINGKUNGAN, IDPEL, THBLMUT, JENIS_MK, UNITUPI, UNITAP, UNITUP, UNITKJ, POSTINGPDL, TGLENTRIPDL, TGLRUBAH_MK, TGLCATAT, CATATBY, TGLUPDATE, UPDATEBY, TGLPEREMAJAAN, PEREMAJAANBY, NAMA, NOURUTPLG, NPWP, KDTARIP_CIS, NOBANG, KETNOBANG, RT, RW, NODLMRT, KETNODLMRT, KODEPOS, KDANGSA, RPANGSA, LAMAANGSA, THBLANGS1A, ANGSKEA, KDANGSB, RPANGSB, LAMAANGSB, THBLANGS1B, ANGSKEB, KDANGSC, RPANGSC, LAMAANGSC, THBLANGS1C, ANGSKEC, NOBP, TGLBP, RPBP, NOUJL, TGLUJL, RPUJL, KDDK, KDBACAMETER, SUBKOGOL, COPYREK, KDMETERAI, KDPPJ, LOKETTGK, KDKVAMAKS, DAYABPT, KDDAYABPT, TGLPASANG_KWH, MEREK_KWH, TYPE_KWH, NOMETER_KWH, THTERA_KWH, THBUAT_KWH, KDDK_AWAL_LWBP, KDDK_AWAL_WBP, NOPABRIK_KWH, NOREGISTER_KWH, FASA_KWH, STAND_CABUT_LWBP, STAND_CABUT_WBP, KDPEMBMETER_KWH, TGLPASANG_KVARH, MEREK_KVARH, TYPE_KVARH, NOMETER_KVARH, THTERA_KVARH, THBUAT_KVARH, KDDK_AWAL_KVARH, NOPABRIK_KVARH, NOREGISTER_KVARH, FASA_KVARH, STAND_CABUT_KVARH, KDPEMBMETER_KVARH, TGLPASANG_KVAMAKS, MEREK_KVAMAKS, TYPE_KVAMAKS, NOMETER_KVAMAKS, THTERA_KVAMAKS, THBUAT_KVAMAKS, KDDK_AWAL_KVAMAKS, NOPABRIK_KVAMAKS, NOREGISTER_KVAMAKS, FASA_KVAMAKS, STAND_CABUT_KVAMAKS, KDPEMBMETER_KVAMAKS, TGLPASANG_CTPTKWH, CT_PRIMER_KWH, CT_SEKUNDER_KWH, PT_PRIMER_KWH, PT_SEKUNDER_KWH, KONSTANTA_KWH, FAKMKWH, TGLPASANG_CTPTKVARH, CT_PRIMER_KVARH, CT_SEKUNDER_KVARH, PT_PRIMER_KVARH, PT_SEKUNDER_KVARH, KONSTANTA_KVARH, FAKMKVARH, TGLPASANG_CTPTKVAMAKS, CT_PRIMER_KVAMAKS, CT_SEKUNDER_KVAMAKS, PT_PRIMER_KVAMAKS, PT_SEKUNDER_KVAMAKS, KONSTANTA_KVAMAKS, FAKMKVAM, THTERA_PEMBATAS, NOPEMBATAS, TGLPASANG_PEMBATAS, THBUAT_PEMBATAS, JENIS_PEMBATAS, UKURANSETTING_PEMBATAS, ARUS_PEMBATAS, TEGANGAN_PEMBATAS, FASA_PEMBATAS, TGLPASANG_SAKLARWAKTU, NOMOR_SAKLARWAKTU, THBUAT_SAKLARWAKTU, THTERA_SAKLARWAKTU, TGLPASANG_SL, KDGARDU, NOTIANG, NOSL, PANJANG_SL, FASA_SL, KDIJIN_WBP, KDINSTALATIR, KODELOKASIDESA, KEL_DESA, KECAMATAN, KODYA_KAB, MSG1, MSG2, BATCHID, F_KETBP, F_KETUJL, KDKOMERSIL, LWBP, WBP, KDGMP, NOSPJBTL, TGLSPJBTL, J_ARUSKWH, G_STANGS1, G_STANGS2, G_STANGS3, G_NOBUKTI1, G_TGLBUKTI1, G_NOBUKTI2, G_TGLBUKTI2, G_NOBUKTI3, G_TGLBUKTI3, UBAHGANTINAMA, TGL_PENGESAHAN, SAH_BY, NOAGENDA, NOPEL, FAKNPREMIUM, PEMASARAN, STS_PRIMA, DAYAJBST, KDDAYAJBST, TGLAWLJBST, TGLAKHJBST, TGLBYREMIN, RPEMINJBST, KWHEMINJBST, BTSKWHREG, KDBEDAJBST, NOKUITEMIN, KDPROSES, KDPDPJ, NOTELP, KDINVOICE, KOORDINATX, KOORDINATY, NO_PABRIK, (SELECT NVL(MAX(KOREKSIKE)+1,0)  FROM BILL52.TRANS_PDL_LOG WHERE IDPEL=A.IDPEL) KOREKSIKE, in_tiket LOG_BY, sysdate TGL_LOG, IDPEL_TTG, TYPE_CT_KWH, TYPE_CT_KVARH, TYPE_CT_KVAMAX, RPSEWATRAFO, NOIDENTITAS from bill52.trans_pdl A where A.noagenda=in_noagenda;


         out_rowcount := SQL%ROWCOUNT;

         UPDATE BILL52.TRANS_101
            SET PNJ = in_pnj_101, NOBANG = in_nobang_101, KETNOBANG = in_ketnobang_101
                WHERE NOAGENDA=in_noagenda;
          
          UPDATE BILL52.TRANS_101_PEMOHON
            SET PNJ_PEMOHON = in_pnj_pemohon, NOBANG_PEMOHON = in_nobang_pemohon, KETNOBANG_PEMOHON = in_ketnobang_pemohon
                WHERE NOAGENDA=in_noagenda;
          
          UPDATE BILL52.TRANS_106
            SET PNJ = in_pnj_106, NOBANG = in_nobang_106, KETNOBANG = in_ketnobang_106
                WHERE NOAGENDA=in_noagenda;
          
--          UPDATE BILL52.TRANS_PDL
--            SET PNJ = in_pnj_106
--                WHERE NOAGENDA=in_noagenda;

         out_rowcount := SQL%ROWCOUNT;

         IF out_rowcount > 0
         THEN
            COMMIT;
            msgerror := ' Sukses';
         ELSE
            msgerror := 'Gagal Update Data PNJ OR NOBANG OR KETNOBANG!';
         END IF;
      END IF;

      INSERT INTO OPHAR_LOG_PROSES (no_tiket,
                                    jenis_transaksi,
                                    no_pelanggan,
                                    tglproses,
                                    login)
           VALUES (in_tiket,
                   'UPDATE PNJ OR NOBANG OR KETNOBANG NULL',
                   in_noagenda,
                   SYSDATE,
                   in_plogin);

      COMMIT;
   END;
   

PROCEDURE save_koreksi_tarif  (in_plogin	IN     VARCHAR2,
                              in_tiket		IN     VARCHAR2,
                              in_noagenda	IN     VARCHAR2,
                              out_rowcount	OUT NUMBER,
                              msgerror		OUT VARCHAR2)
   IS
      vjml         NUMBER;
   BEGIN
      SELECT COUNT (*)
        INTO vjml
        FROM BILL52.TRANS_MUTASI_KOREKSI a
       WHERE a.NOAGENDA = in_noagenda;


      IF vjml = 0
      THEN
         msgerror := 'Data tidak ditemukan!';
      ELSE

	INSERT INTO OPHARAPP.TRANS_MUTASI_KOREKSI_LOG 
    		SELECT A.*,SYSDATE TGLLOG,in_tiket LOGBY 
    	FROM BILL52.TRANS_MUTASI_KOREKSI A WHERE NOAGENDA=in_noagenda;

         out_rowcount := SQL%ROWCOUNT;

         UPDATE BILL52.TRANS_MUTASI_KOREKSI A 
		SET TGLREMAJA = (SELECT TGLPEREMAJAAN FROM BILL52.TRANS_PDL WHERE NOAGENDA=A.NOAGENDA),
            PETUGASREMAJA = (SELECT PEREMAJAANBY FROM BILL52.TRANS_PDL WHERE NOAGENDA=A.NOAGENDA) 
        WHERE NOAGENDA=in_noagenda;

         out_rowcount := SQL%ROWCOUNT;

         IF out_rowcount > 0
         THEN
            COMMIT;
            msgerror := ' Sukses';
         ELSE
            msgerror := 'Gagal Update Data Koreksi Tarif!';
         END IF;
      END IF;

      INSERT INTO OPHAR_LOG_PROSES (no_tiket,
                                    jenis_transaksi,
                                    no_pelanggan,
                                    tglproses,
                                    login)
           VALUES (in_tiket,
                   'UPDATE REMAJA KOREKSI TARIF',
                   in_noagenda,
                   SYSDATE,
                   in_plogin);

      COMMIT;
   END;
      
END PKG_PNJ_NULL;
/